BEGIN;
INSERT INTO public.exams (slug,title,source,year) VALUES ('esa-2026-geral','ESA 2026 · Geral / Aviação','esa','2026')
ON CONFLICT (slug) DO UPDATE SET title=excluded.title,source=excluded.source,year=excluded.year;
WITH data AS (SELECT '{"slug": "esa-2026-geral", "source": "esa", "year": "2026", "title": "ESA 2026 · Geral / Aviação", "questions": [{"number": 1, "subject": "Matemática", "text": "A robótica tem se tornado cada vez mais presente nas Forças Armadas. Robôs são desenvolvidos e empregados para aumentar a segurança dos combatentes e executar tarefas em que são guiados por meio de controle remoto. Durante um exercício no Campo de Instrução da Escola de Sargentos das Armas, um robô, que se encontra na origem de um sistema cartesiano ortogonal, deve passar pelos pontos A(1,1), B(2,0) e C(4,4), que também estão no mesmo plano cartesiano. Inicialmente, ele deve caminhar em linha reta até o ponto A. Em seguida, deve ajustar sua trajetória para deslocar-se sobre um arco parabólico, a fim de passar pelos pontos B e C. Dessa forma, o robô deve ser programado para deslocar-se sobre o gráfico da função:\nf(x) = mx, se 0 ≤ x ≤ 1;\nf(x) = ax² + bx + c, se x > 1.\nNesse caso, a² + b² + c² + m² é igual a:", "support": null, "support_image": null, "options": ["32", "34", "36", "38", "40"], "answer": "B", "explanation": null, "page": 2}, {"number": 2, "subject": "Matemática", "text": "A figura abaixo representa o gráfico da função f: ℝ₊* → ℝ definida por f(x) = log₂x. A área da região sombreada é numericamente igual a:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q2-figura-1.png", "options": ["10", "12", "16", "18", "20"], "answer": "B", "explanation": null, "page": 2}, {"number": 3, "subject": "Matemática", "text": "A Escola de Sargentos das Armas (ESA) oferece as qualificações militares nas armas de\nInfantaria, Cavalaria, Artilharia, Engenharia e Comunicações. O fuzil, o carro de combate,\no obuseiro, as máquinas de engenharia e os rádios são objetos que caracterizam essas\narmas, respectivamente. A fim de divulgar o Exército Brasileiro, a ESA montará uma exposição\ncom pelo menos um objeto de cada arma, num total de 12 objetos. Se a ESA possui objetos em\nnúmero suficiente e os objetos de cada arma são idênticos, de quantas maneiras diferentes a\nexposição poderá ser montada se ela será em linha e obedecendo ao espaço reservado,\nconforme esquema abaixo?", "support": null, "support_image": "/militares-2026/esa-2026-geral-q3-figura-1.png", "options": ["165", "215", "330", "495", "615"], "answer": "C", "explanation": null, "page": 2}, {"number": 4, "subject": "Matemática", "text": "Em um triângulo equilátero (∆DEF) de perímetro igual a 60 cm, traça-se um segmento de\nreta com origem no ponto médio do lado DE até o ponto R, que se encontra sobre o\nprolongamento do segmento EF , sendo que: FR = 15 cm. Assim, o valor correto da\nmedida de F até o ponto de interseção com o lado DF é:", "support": null, "support_image": null, "options": ["30 cm", "24 cm", "15 cm", "8 cm", "6 cm"], "answer": "E", "explanation": null, "page": 2}, {"number": 5, "subject": "Matemática", "text": "Visando à preparação para a MAREXAER, competição esportiva entre as três escolas de\nformação de sargentos da Marinha do Brasil, do Exército Brasileiro e da Força Aérea\nBrasileira, um número x de alunos da ESA foi selecionado para participar de uma pesquisa,\nvisando verificar a preferência deles para três modalidades esportivas. Os resultados foram\ntabelados abaixo:\nA probabilidade de se escolher um aluno que tenha preferência por, no máximo, uma modalidade\nanalisada, entre os x alunos selecionados inicialmente para a pesquisa, é igual a 21/40. Nessas\ncondições, o número de alunos entre os x selecionados inicialmente que não manifestaram\ninteresse por qualquer das modalidades analisadas é:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q5-figura-1.png", "options": ["12", "16", "24", "32", "40"], "answer": "B", "explanation": null, "page": 3}, {"number": 6, "subject": "Matemática", "text": "Um professor de Matemática aplicou uma prova contendo 5 questões, valendo 1 ponto\ncada uma, a 25 alunos de uma sala. Após fazer a correção, o professor construiu o gráfico\nabaixo, que relaciona o número de alunos às notas obtidas por eles:\nAnalisando o gráfico, conclui-se que a soma da média, da moda e da mediana das notas obtidas\npelos alunos é igual a:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q6-figura-1.png", "options": ["9,15", "9,96", "8,35", "8,15", "8,59"], "answer": "B", "explanation": null, "page": 3}, {"number": 7, "subject": "Matemática", "text": "As raízes do polinômio p(x) = 2x³ − mx² + 17x − 6 são a, b e 2, com a > b. Nesse caso, é correto afirmar que aᵇ é igual a:", "support": null, "support_image": null, "options": ["1", "√2", "2", "√3", "4"], "answer": "D", "explanation": null, "page": 3}, {"number": 8, "subject": "Matemática", "text": "Um cilindro, cujo raio da base mede 20 cm, possui água em seu interior até a altura de 10 cm. Três esferas metálicas (E₁, E₂ e E₃, nessa ordem) possuem os raios com medidas que seguem uma progressão geométrica. O raio da esfera E₁ mede 3 cm. Quando essas esferas são colocados no interior do cilindro, o nível da água sobe 6,57 cm. Assim, pode-se afirmar que o volume da esfera E₂ é igual a:", "support": null, "support_image": null, "options": ["36π cm³", "72π cm³", "180π cm³", "240π cm³", "288π cm³"], "answer": "E", "explanation": null, "page": 3}, {"number": 9, "subject": "Matemática", "text": "O pelotão de obras da Escola de Sargentos das Armas recebeu a missão de\nreconhecimento topográfico, que consiste em calcular a área de um terreno triangular ABC,\nilustrado na figura abaixo.\nOs pontos A e B foram acessados normalmente, mas o ponto C estava dentro de uma área\nminada, portanto, inacessível por questões de segurança. Para cumprir a missão, o comandante\ndo pelotão mediu os ângulos CÂB, CB̂A e a distância AB, obtendo, respectivamente, α, β e a. Qual\na área do triângulo encontrada pelo comandante?", "support": null, "support_image": "/militares-2026/esa-2026-geral-q9-figura-1.png", "options": ["(a²senα∙senβ)/(2sen(α+β))", "(a²senα)/(senα+senβ)", "(a²senβ)/(senα+senβ)", "(a²sen(α+β))/(2senα∙senβ)", "(a²sen(α+β))/(senα∙senβ)"], "answer": "A", "explanation": null, "page": 4}, {"number": 10, "subject": "Matemática", "text": "Observe o paralelepípedo ABCDEFGH.\nMarque a única alternativa correta entre as afirmações abaixo:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q10-figura-1.png", "options": ["As retas BE e FG são coplanares.", "Os vértices A, B e G não definem um plano.", "As retas BC e EF são ortogonais.", "As retas AE e BF são reversas.", "Os vértices C, E, H e G pertencem a um mesmo plano."], "answer": "C", "explanation": null, "page": 4}, {"number": 11, "subject": "Matemática", "text": "Se log de ⁴√3 na base ¹⁰⁸√(1/3), log de √3 na base ¹⁸√3 e log de (√10)⁻⁶ formam, nessa ordem, uma PG, qual o valor aproximado da soma dos 8 primeiros termos:", "support": null, "support_image": null, "options": ["−20,25", "20,25", "25,25", "−25,25", "−23,25"], "answer": "A", "explanation": null, "page": 4}, {"number": 12, "subject": "Matemática", "text": "Um baralho possui 52 cartas, que são divididas em 4 naipes diferentes (ouros, copas, paus\ne espadas), cada um destes possui 13 cartas, das quais são: 9 numéricas de “2 a 10”,\nValete (J), Dama (Q), Rei (K) e Ás (A). A probabilidade de a primeira carta retirada ser um\nREI e a segunda carta NÃO ser REI nem DAMA é:", "support": null, "support_image": null, "options": ["44/663", "45/663", "176/663", "48/663", "50/663"], "answer": "A", "explanation": null, "page": 4}, {"number": 13, "subject": "Matemática", "text": "A administração de um pequeno shopping fez um estudo com o objetivo de melhorar a\nfrequência. Um dos engenheiros responsáveis por esse estudo observou que a frequência\nque representa essa situação pode ser expressa pela função f(x) = 700 + |225 − 15x|,\nsendo 1 ≤ x ≤ 30, em que x representa o dia do mês e f(x) a quantidade de pessoas que\nfrequentam esse pequeno shopping nesse dia (considere o mesmo horário de funcionamento\npara todos os dias do mês). Com base no enunciado, avalie as afirmações abaixo em verdadeiro\n(V) ou falso (F).\nl. O dia mais frequentado nesse shopping é o 30° dia.\nll. O dia menos frequentado nesse shopping é o 15° dia.\nlll. No 15° dia, a quantidade de pessoas que frequentou esse shopping é zero.\nlV. No dia 30, a quantidade de pessoas que frequentou esse shopping foi de 225.\nV. No dia 25, a quantidade de pessoas que frequentou esse shopping foi de 850.\nMarque a alternativa que representa a sequência correta com relação às afirmações acima:", "support": null, "support_image": null, "options": ["V – V – F – F – F", "F – F – V – V – F", "V – F – F – V – F", "F – F – V – V – V", "V – V – F – F – V"], "answer": "E", "explanation": null, "page": 5}, {"number": 14, "subject": "Matemática", "text": "A figura abaixo representa uma mesa de sinuca em forma elíptica de focos F₁ e F₂ e distância focal igual a 8. A sinuca possui uma única caçapa localizada em F₂. Um jogador deseja jogar nessa caçapa a bola que se encontra no ponto A. Entretanto, ele não consegue fazer isso diretamente, pois existe uma bola em B que está localizado entre A e F₂. Para cumprir o objetivo, o jogador resolve fazer uma ‘tabela’, ou seja, jogar a bola na parede da sinuca para que ela reflita em direção a F₂. Considerando que o sistema cartesiano tenha origem no centro da elipse e que o ponto A tem coordenadas (−2, −2), qual das equações abaixo dá a direção para que o jogador cumpra seu objetivo?", "support": null, "support_image": "/militares-2026/esa-2026-geral-q14-figura-1.png", "options": ["2x + y + 8 = 0", "3x − y + 12 = 0", "x + 2y + 6 = 0", "x + y + 4 = 0", "3x − 2y + 2 = 0"], "answer": "D", "explanation": null, "page": 5}, {"number": 15, "subject": "Língua Portuguesa", "text": "Com base no uso da vírgula no último período do Texto I – “Os minutos passavam, como\npassam em qualquer lugar” – assinale a alternativa correta:", "support": "TEXTO I\n“Nasceu o sol. E, como ela estava com tempo, sentou-se num banco do jardim. Um homem\nmastigava chicletes. Outro lia jornal. Uma mulher estava parada, com um saco de pão no colo. A\nvida era aquilo. Os minutos passavam, como passam em qualquer lugar.”\nBecker, A. Armandinho. Disponível em:\nhttps://fotografia.folha.uol.com.br/galerias/27431-tiras-de-armandinho. Acesso em: 7 de outubro de 2024.", "support_image": null, "options": ["A vírgula está incorreta, pois separa sujeito e predicado, o que fere a norma-padrão.", "A vírgula separa duas orações coordenadas assindéticas com sujeitos distintos, o que justifica seu uso.", "A vírgula isola uma oração subordinada adverbial comparativa, o que está de acordo com a norma-padrão.", "O uso da vírgula é inadequado, pois o advérbio “como” não exige isolamento da oração seguinte.", "A vírgula marca uma enumeração de ações no tempo."], "answer": "C", "explanation": null, "page": 6}, {"number": 16, "subject": "Língua Portuguesa", "text": "Assinale a alternativa que apresenta erro de grafia.", "support": null, "support_image": null, "options": ["Conciliador – adjetivo que indica alguém que busca conciliação.", "Imprescindível – palavra que significa algo absolutamente necessário.", "Assintomático – termo usado para indicar ausência de sintomas.", "Excessão – substantivo que significa ato ou efeito de excluir.", "Paralelogramo – figura geométrica com dois pares de lados paralelos."], "answer": "D", "explanation": null, "page": 6}, {"number": 17, "subject": "Língua Portuguesa", "text": "De acordo com o Texto II, qual é a principal exigência que a revolução digital impõe à\neducação?", "support": "TEXTO II\n“A revolução digital já não é uma promessa, mas uma realidade concreta. Ela molda a forma\ncomo nos comunicamos, consumimos e trabalhamos. Isso impõe novos desafios à educação,\nque precisa não apenas se adaptar, mas também liderar mudanças.”\nBARROS, M. L. Educação na era digital. Revista Educação em Pauta, n. 34, 2022.", "support_image": null, "options": ["A educação deve manter os métodos tradicionais para garantir estabilidade.", "A educação deve aguardar que a tecnologia se estabilize para se adaptar.", "A educação deve limitar o uso de tecnologias em sala de aula.", "A educação precisa apenas se adaptar às novas tecnologias.", "A educação deve se adaptar e também liderar mudanças diante dessa revolução."], "answer": "E", "explanation": null, "page": 6}, {"number": 18, "subject": "Língua Portuguesa", "text": "Observe o trecho abaixo extraído do Texto III:\n“vento assobiava no intervalo do vento”\nAssinale a alternativa que indica uma das figuras de linguagem representadas pelo trecho acima:", "support": "TEXTO III\n“Dormia tudo como se o universo fosse um erro; e o vento, flutuando incerto, era uma bandeira\nsem forma desfraldada sobre um quartel sem ser.\nEsfarrapava-se coisa nenhuma no ar alto e forte, e os caixilhos das janelas sacudiam os vidros\npara que a extremidade se ouvisse. No fundo de tudo, calada, a noite era o túmulo de Deus (a\nalma sofria com pena de Deus).\nE, de repente — nova ordem das coisas universais agia sobre a cidade –, o vento assobiava no\nintervalo do vento, e havia uma noção dormida de muitas agitações na altura. Depois a noite\nfechava-se como um alçapão, e um grande sossego fazia vontade de ter estado a dormir.”\nPESSOA, Fernando. Livro do Desassossego. Disponível em:\nhttps://agrcanelas.edu.pt/blogs/biblioteca/files/2012/11/Livro-do-Desassossego-.pdf. Acesso em: 5 de agosto de 2025. (Fragmento)", "support_image": null, "options": ["Antítese", "Eufemismo", "Prosopopeia", "Ironia", "Hipérbole"], "answer": "C", "explanation": null, "page": 7}, {"number": 19, "subject": "Língua Portuguesa", "text": "Considerando a colocação pronominal no Texto IV, assinale a única alternativa em que\nseria possível deslocar o pronome “me” sem violar as regras gramaticais.", "support": "TEXTO IV\n“— Perdoai-me, senhora, aqui me tendes a vossos pés! tende pena de mim que eu sofri muito,\nque amei-vos, que vos amo muito! Compaixão! que serei vosso escravo, (...) ajoelhar-me-ei à\nnoite à vossa porta, ouvirei vosso ressonar, vossas orações, vossos sonhos — e isso me bastará.\n— Serei vosso escravo e vosso cão, deitar-me-ei a vossos pés quando estiveres acordada, velarei\ncom meu punhal quando a noite cair: e, se algum dia, se algum dia vós me puderes amar... então!\nentão! ...”\nAZEVEDO, Àlvares de. Noite na taverna. Porto Alegre: L & PM, 2009. p. 69.", "support_image": null, "options": ["Em “perdoai-me, senhora”, o pronome poderia ser destacado para antes do verbo, “me perdoai” já que o vocativo funciona como fator de atração para próclise.", "Em “ajoelhar-me-ei à noite à vossa porta”, a forma “me ajoelharei” seria aceita, pois há ideia de futuro e ausência de atrativos, que o permite liberdade na colocação.", "Em “deitar-me-ei a vossos pés”, o pronome pode ser anteposto ao verbo “me deitarei” considerando a familiaridade de forma na linguagem contemporânea.", "Em “aqui me tendes a vossos pés”, o pronome pode ser posposto ao verbo, pois seu emprego é facultativo com a presença do advérbio.", "Em “vós me puderes amar”, a estrutura verbal “puderes amar”, formada por dois verbos, admite o deslocamento do pronome antes dos dois verbos, entre ou depois deles."], "answer": "E", "explanation": null, "page": 7}, {"number": 20, "subject": "Língua Portuguesa", "text": "Com base na estrutura sintática e nas relações semântico-discursivas estabelecidas pelas\norações subordinadas adverbiais presentes no Texto V, assinale a alternativa que identifica\ncorretamente, na ordem em que aparecem, os valores lógicos das orações subordinadas:", "support": "TEXTO V\n“Mesmo que persista certa desconfiança de familiares e professores sobre o uso de dispositivos\neletrônicos móveis na sala de aula, gestores do ensino público e particular começam a correr\natrás da adaptação do conteúdo didático para formatos digitais, uma vez que, antes mesmo de\nlargar as fraldas, um número cada vez maior de crianças já tem mais o que fazer com os dedinhos\ndo que roer unhas.”\nMING, Celso. Mochila digital. O Estado de S. Paulo, 1º fev.2014. Disponível em:\neconomia.estadao.com.br/blogs/celso. Acesso em: 06 de agosto de 2025.", "support_image": null, "options": ["concessiva — causal — temporal — comparativa", "condicional — explicativa — proporcional — consecutiva", "concessiva — explicativa — temporal — proporcional", "condicional — causal — concessiva — comparativa", "concessiva — causal — concessiva — consecutiva"], "answer": "A", "explanation": null, "page": 8}, {"number": 21, "subject": "Língua Portuguesa", "text": "Com base no Texto VI, sobre o papel da competência linguística na formação e atuação\ndo sargento, é correto afirmar que:", "support": "TEXTO VI\n“No ambiente militar contemporâneo, a competência linguística do sargento – entendida como a\ncapacidade de ler criticamente, interpretar contextos e expressar-se com clareza – assume papel\nestratégico. Um sargento que domina a linguagem é capaz de compreender instruções\ncomplexas, redigir relatórios precisos e, sobretudo, liderar com autoridade comunicativa. Assim,\na leitura e a escrita deixam de ser habilidades acessórias e tornam-se instrumentos de ação tática\ne administrativa, cuja ausência compromete o desempenho e a credibilidade do profissional.”\nBRASIL. Ministério da Defesa. Exército Brasileiro. A linguagem como instrumento estratégico na atuação do sargento.\nRevista Verde-Oliva, Brasília, n. 530, p. 19, 2022.", "support_image": null, "options": ["A competência linguística é uma exigência exclusiva das funções administrativas, não interferindo nas atividades táticas realizadas em campo.", "A clareza na comunicação é desejável, mas não constitui fator determinante para a autoridade e o desempenho do sargento.", "O domínio da linguagem pelo sargento é um elemento estratégico que impacta diretamente sua capacidade de liderar, interpretar ordens e agir com eficiência.", "A leitura e a escrita são habilidades complementares que podem ser delegadas a superiores, não sendo centrais à função do sargento.", "A exigência por competências linguísticas é uma tendência recente, mas opcional, e não afeta significativamente o dia a dia militar."], "answer": "C", "explanation": null, "page": 8}, {"number": 22, "subject": "Língua Portuguesa", "text": "Analise as afirmações abaixo e assinale a única alternativa que apresenta erro de\nconcordância verbal, de acordo com a norma-padrão da Língua Portuguesa.", "support": null, "support_image": null, "options": ["Faltaram explicações claras sobre os procedimentos adotados durante a operação.", "Haveriam problemas graves se a tropa não seguisse as instruções corretamente.", "Chegaram, por fim, os reforços que haviam sido solicitados pelo comandante.", "Permanecem em alerta os soldados que não participaram da missão anterior.", "Não é admissível que se percam informações tão relevantes por descuido."], "answer": "B", "explanation": null, "page": 8}, {"number": 23, "subject": "Língua Portuguesa", "text": "Leia o Texto VII e marque a alternativa incorreta em relação à análise morfossintática:", "support": "TEXTO VII\n“O Exército pode passar cem anos sem ser usado, mas não pode passar um minuto sem estar\npreparado.”\nBARBOSA, Rui. Disponível em: https://www.pensador.com/frases_de_rui_barbosa/. Acesso em: 05 de agosto de 2025.", "support_image": null, "options": ["É um período composto, pois observam-se vários componentes verbais.", "O texto exemplifica um período composto, porque o sujeito é indeterminado.", "No trecho “O Exército pode passar cem anos...” o sujeito é simples.", "Em “...mas não pode passar um minuto...”, o “não” é adjunto adverbial.", "No excerto “...não pode passar um minuto sem...”, o “pode passar” é uma locução verbal."], "answer": "B", "explanation": null, "page": 9}, {"number": 24, "subject": "Língua Portuguesa", "text": "Com base na leitura do Texto VIII, a palavra “encharcava”, em “mas encharcava a alma”,\ntem como significado principal:", "support": "TEXTO VIII\n“E era como se chovesse. Chovia dentro dele. Não águas, mas sentimentos, lembranças, culpas\nantigas. Uma chuva que não molhava a pele, mas encharcava a alma.”\nABREU, Caio Fernando. Os dragões não conhecem o paraíso. Disponível em:\ncontobrasileiro.com.br/alem_do_ponto_conto_de_caio_fernando_abreu/. Acesso em 06 de agosto de 2025. (Adaptado)", "support_image": null, "options": ["Tornava a alma mais pesada, como se fosse feita de pedra.", "Inundava a alma de emoções, de forma intensa e profunda.", "Deixava a alma seca, exaurida pelas lembranças.", "Limpava a alma de todas as culpas passadas.", "Cobria a alma com uma camada superficial de sentimentos passageiros."], "answer": "B", "explanation": null, "page": 9}, {"number": 25, "subject": "Língua Portuguesa", "text": "Analisando o Texto IX, é correto afirmar que a personagem principal está em um estado\nemocional de:", "support": "TEXTO IX\n“Subi à carruagem que me aguardava, e, tão logo me acomodei, dei a ordem ao cocheiro. Durante\no trajeto, os pensamentos se agitavam em minha mente, tumultuados e contraditórios. Algumas\nlembranças me assaltaram como vultos do passado, outras se dissipavam com o tempo. As ruas\nestavam silenciosas, e o luar conferia à cidade um aspecto quase onírico. Não sabia se era a\nnostalgia ou a dúvida o que mais me dominava. O coração apertava-se com uma dor estranha,\ncomo se a consciência me cobrasse escolhas já feitas. Tinham-se perdido, talvez, os últimos\nfragmentos da serenidade que outrora possuíra. Ou talvez não fosse a serenidade, mas a\nesperança, que lentamente se desfazia dentro de mim.”\nALENCAR, José de. Senhora. São Paulo: Martin Claret, 2009 (Adaptado)", "support_image": null, "options": ["Euforia e entusiasmo, devido à expectativa do que o futuro lhe reserva.", "Calma e serenidade, pois a viagem de carruagem a tranquiliza.", "Medo e ansiedade, temendo um perigo iminente durante o percurso.", "Melancolia e incerteza, refletindo sobre perdas e decisões passadas.", "Saudosismo e alegria, lembrando-se de momentos felizes de seu passado."], "answer": "D", "explanation": null, "page": 9}, {"number": 26, "subject": "Língua Portuguesa", "text": "O Texto X pertence a uma das obras mais representativas da literatura portuguesa.\nConsiderando as características formais e históricas da arte literária, assinale a alternativa\ncorreta:", "support": "TEXTO X\n“As armas e os barões assinalados\nQue da ocidental praia Lusitana\nPor mares nunca de antes navegados\nPassaram ainda além da Taprobana,\nEm perigos e guerras esforçados\nMais do que prometia a força humana,\nE entre gente remota edificaram\nNovo Reino, que tanto sublimaram.”\nCAMÕES, Luís Vaz de. Os Lusíadas. Canto I, estrofe 1", "support_image": null, "options": ["O excerto é um exemplo típico da lírica medieval portuguesa, que exaltava a fé cristã e os valores teocêntricos, típicos da literatura trovadoresca.", "Os Lusíadas pertence ao gênero dramático e foi composto para ser encenado em cortes e castelos, conforme a tradição do teatro vicentino renascentista.", "O texto de Camões é uma epopeia renascentista que pertence ao gênero épico, marcada pela exaltação do povo português e pelo culto ao humanismo e ao heroísmo.", "A linguagem do trecho demonstra traços típicos do realismo-naturalismo, como a descrição objetiva dos navegadores e a crítica às instituições religiosas da época.", "A epopeia camoniana inaugurou o barroco em Portugal, ao fundir os valores clássicos com o dilema existencial do homem entre o mundo e Deus."], "answer": "C", "explanation": null, "page": 10}, {"number": 27, "subject": "Língua Portuguesa", "text": "Assinale, dentre as alternativas abaixo, aquela em que apresenta a mesma figura de\nlinguagem presente no seguinte trecho:\n“Vão os dois em diálogo peripatético, ele em passo largo, ela no voo.”\nANDRADE, Carlos Drummond de. Cadeira de balanço. Rio de Janeiro: Record, 1970.", "support": null, "support_image": null, "options": ["“A barca vinha de perto, chegou, atracou, entramos.” (Machado de Assis)", "“O bonde, cuspindo e engolindo gente, mergulhava nas saborosas entranhas de Belém.” (Dalcídio Jurandir)", "“E se os olhos reaprendessem a chorar, seria um segundo dilúvio.” (Carlos Drummond de Andrade)", "“Se chegar depois das três, a casa fechada. A mala na varanda. E o táxi na porta.” (Dalton Trevisan)", "“Deixa lá, que ainda havemos de ser feliz os dois, com a nossa casinha e as nossas coisas.” (Almada Negreiros)"], "answer": "D", "explanation": null, "page": 10}, {"number": 28, "subject": "Língua Portuguesa", "text": "Assinale a alternativa em que todas as palavras foram acentuadas seguindo a mesma\nregra de acentuação gráfica.", "support": null, "support_image": null, "options": ["açúcar - difícil - só", "ônix - mês - água", "sofá - júri - útil", "é - só - mês", "álbum - câmara - júri"], "answer": "D", "explanation": null, "page": 10}, {"number": 29, "subject": "História", "text": "Considerações políticas levaram a\nCoroa portuguesa à convicção de que\nera necessário colonizar a nova terra na\nAmérica. Ficou decidido que o modelo seria\nde capitanias hereditárias. A América\nportuguesa foi dividida, à época, em quinze\nquinhões, por uma série de linhas paralelas\nao Equador que iam do litoral ao meridiano\nde Tordesilhas, sendo os quinhões\nentregues aos chamados capitãesdonatários.\nFonte: disponível em: https://www.todamateria.com.br/capitanias-hereditarias/. Acesso em: 13 de agosto de 2025 (Adaptada)\nSelecione entre as alternativas abaixo as características das capitanias mais prósperas:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q29-figura-1.png", "options": ["atividade açucareira e um relacionamento menos agressivo com as tribos indígenas.", "atividade mineradora e um relacionamento menos agressivo com as tribos indígenas.", "atividade de extração do pau-brasil e um relacionamento menos agressivo com as tribos indígenas.", "atividade açucareira e um relacionamento mais agressivo com as tribos indígenas.", "atividade mineradora e um relacionamento mais agressivo com as tribos indígenas."], "answer": "A", "explanation": null, "page": 11}, {"number": 30, "subject": "História", "text": "O Império do Brasil acompanhava com atenção as evoluções geopolíticas na região da\nBacia do Rio da Prata. Era uma área de grande importância, porque controlava o acesso\nao interior e, especialmente, à província do Mato Grosso. Neste sentido, a Guerra contra Oribe\ne Rosas ocorreu porque:", "support": null, "support_image": null, "options": ["Dom Pedro II queria recuperar a Província Cisplatina.", "A ocupação de Montevidéu por Oribe rompeu o equilíbrio estabelecido em 1828.", "Manuel Oribe tinha a intenção de formar um novo Estado com o Rio Grande do Sul.", "José Urquiza, governador da província de Corrientes, preparava a invasão do Mato Grosso.", "Rivera organizava o exército paraguaio para unir-se a Urquiza contra o Império do Brasil."], "answer": "B", "explanation": null, "page": 11}, {"number": 31, "subject": "História", "text": "Luís Alves de Lima e Silva, futuro Duque de Caxias, comandou a ação militar imperial\ncontra os farrapos. Hábil negociador, Caxias procurou estabelecer acordos com os líderes\nfarroupilhas, a fim de alcançar a paz. Os fazendeiros gaúchos, para atender ao exército farrapo,\nincluíram as seguintes exigências:", "support": null, "support_image": null, "options": ["Liberdade para os escravos e maior participação política da população.", "A separação do Império do Brasil e a criação de uma República Rio-Grandense.", "Anistia do imperador aos revoltosos e a incorporação dos militares ao exército imperial.", "A incorporação dos militares ao exército imperial e a anexação da Província Cisplatina.", "Liberdade para todos os escravos no Brasil e máxima autonomia para a província de São Pedro do Rio Grande do Sul."], "answer": "C", "explanation": null, "page": 12}, {"number": 32, "subject": "História", "text": "Dentre as características da Constituição de 1891, a primeira do Brasil República, podemos\nassinalar:", "support": null, "support_image": null, "options": ["O voto censitário foi abolido, sendo estabelecido o direito de voto a todos os homens maiores de 18 anos.", "A Constituição estabeleceu um sistema de eleições indiretas à Presidência da República pelo Congresso, o que levou os estados mais populosos (São Paulo e Minas Gerais) ao controle da Presidência.", "Os deputados federais seriam eleitos para um mandato de 4 anos e os senadores para um mandato de 8 anos.", "A Constituição proibia explicitamente os estados de contrair empréstimos no exterior, sendo esta competência exclusiva da União.", "A autonomia dos estados ficou consagrada ao lhes serem conferidos os poderes e direitos que não lhes fossem negados por dispositivos do texto constitucional."], "answer": "E", "explanation": null, "page": 12}, {"number": 33, "subject": "História", "text": "Apesar de o eixo da economia brasileira durante a Primeira República estar orientado pelos\nnegócios do café, este período também foi marcado por um processo incipiente de\nindustrialização. Nesse sentido, Boris Fausto aponta que o Estado brasileiro não foi inimigo da\nindústria, porém não atuou para estimulá-la:\n“se o Estado não foi um adversário da indústria, esteve longe de promover uma política deliberada de\ndesenvolvimento industrial.”\nFAUSTO, Boris. História do Brasil. 14 ed., atual. e ampl., 4. reimpr. São Paulo: Editora da Universidade de São Paulo, 2024. p. 249\nSobre a industrialização durante a Primeira República, assinale a afirmativa incorreta:", "support": null, "support_image": null, "options": ["São Paulo e Minas Gerais eram, desde o final da década de 1900, os principais centros industriais do país – o que se explica pelo controle exercido sobre o poder central a partir da política do “café com leite”.", "Apesar do relativo avanço da produção industrial no período, havia no país uma profunda carência de indústria de base – de modo que boa parte do surto industrial dependia de importações.", "Os imigrantes tiveram importante papel no processo de industrialização, tanto como donos de empresas como operários – em São Paulo, por exemplo, os imigrantes respondiam por 70% dos integrantes das empresas manufatureiras da capital.", "Na primeira década do século XX, o Rio de Janeiro era o principal centro industrial do país, com o Distrito Federal sendo responsável por 1/3 da produção industrial em 1907.", "O Rio Grande do Sul teve um crescimento industrial importante no período, diferenciando-se de São Paulo, porém, por ter se desenvolvido quase inteiramente em função do mercado interno."], "answer": "A", "explanation": null, "page": 12}, {"number": 34, "subject": "História", "text": "Leia o texto abaixo:\nA conquista de Monte Castelo, ocorrida durante a Segunda Guerra Mundial, foi uma das mais árduas\nbatalhas enfrentadas pela Força Expedicionária Brasileira (FEB) na Campanha da Itália. O dia 21 de\nfevereiro de 1945 será sempre lembrado pelo admirável exemplo de bravura e sacrifício dos nossos\npracinhas. Naquela gélida tarde do inverno europeu, teve sucesso a incursão rumo ao cume do\nCastelo. Sua conquista, um dos mais gloriosos feitos das Armas nacionais, marcou a história do\nExército Brasileiro e contribuiu para acelerar a retirada das tropas alemãs do território italiano. [...]\nA tomada de Monte Castelo traduz o esforço e o sacrifício dos soldados brasileiros na Segunda Guerra\nMundial, consolidando o papel da FEB na libertação da Itália e na luta contra o nazifascismo.\nLembrar Monte Castelo é reverenciar nossos heróis!\n80 anos da tomada de Monte Castelo. Disponível em:\nhttps://www.eb.mil.br/web/central-de-conteudos/w/80-anos-da-tomada-de-monte-castelo. Acesso em 13 de agosto de 2025 (Fragmento)\nO trecho acima foi publicado em homenagem aos 80 anos da tomada do Monte Castelo, no\ncontexto da campanha brasileira durante a Segunda Guerra Mundial. Sobre a participação\nbrasileira neste conflito, podemos afirmar corretamente que:", "support": null, "support_image": null, "options": ["A FEB não foi uma iniciativa imposta pelos Aliados, mas sim uma decisão do governo brasileiro.", "A população recebeu com apatia e revolta a proclamação da guerra, dado o forte sentimento de simpatia existente na população brasileira para com a Itália.", "Devido aos regulamentos segregacionistas então vigentes nas Forças Armadas dos EUA, às quais a tropa brasileira estava subordinada, os negros tiveram sua participação vetada na FEB.", "A entrada do Brasil na guerra foi provocada a partir do desembarque de tropas nazistas no Sul do país, cujo objetivo era o de anexar os estados de Santa Catarina e Rio Grande do Sul ao Reich alemão.", "Aproximadamente 2 mil homens lutaram na Itália, sob o comando do general Góis Monteiro, até o fim do conflito naquele país, em 2 de maio de 1945."], "answer": "A", "explanation": null, "page": 13}, {"number": 35, "subject": "Geografia", "text": "Observe a imagem abaixo:\nFonte: disponivel em https://revistapesquisa.fapesp.br/, acesso em 18/08/2028.\nO problema ambiental climático que está diretamente relacionado à imagem acima é o(a):", "support": null, "support_image": "/militares-2026/esa-2026-geral-q35-figura-1.png", "options": ["El niño.", "Ilha de calor.", "Inversão térmica.", "Aquecimento global.", "Camada de ozônio."], "answer": "B", "explanation": null, "page": 13}, {"number": 36, "subject": "Geografia", "text": "Observe o mapa abaixo:\nFonte: IBGE - Arranjos populacionais e concentrações urbanas no Brasil, 2° edição, IBGE, 2016. Disponível em:\nhttps://biblioteca.ibge.gov.br/index.php/biblioteca-catalogo?view=detalhes&id=299700. Acesso em: 20 de agosto de 2025 (Adaptado)\nSobre a dinâmica populacional abordada no mapa, é correto afirmar que:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q36-figura-1.png", "options": ["trata-se de uma migração sazonal, determinada pela oferta de emprego em períodos determinados de tempo e praticada, em geral, por trabalhadores contratados como mão de obra barata.", "refere-se à migração pendular, comum nas regiões metropolitanas, em que parcela da população migra diariamente do local de moradia, cidades dormitórios, para outras cidades nas quais o elevado custo de vida as impede de morar.", "especializa um tipo de migração forçada, onde parcela da população é obrigada a migrar, em geral por questões de perseguição motivada por divergências políticas, ideológicas, religiosas, etc.", "demonstra a migração de retorno, em que um determinado contingente de migrantes busca retornar para seus locais de origem, que agora lhes oferecem melhores condições de vida e emprego.", "aborda casos de êxodo urbano, que, no caso específico, é motivado pelo elevado grau de violência urbana e pela busca de locais com maior oferta de serviços e empregos que ofereçam melhores salários."], "answer": "B", "explanation": null, "page": 14}, {"number": 37, "subject": "Geografia", "text": "O crescimento populacional, o desenvolvimento de novas tecnologias e a elevação do\npadrão de consumo têm levado ao aumento demanda por energia e à crescente\nnecessidade de aumentar sua produção mundial. Em 2008, dirigentes da Petrobras anunciaram\na descoberta de enormes reservas de petróleo e gás natural a mais de 5 quilômetros de\nprofundidade, na camada pré-sal, conforme imagem abaixo.\nFonte: disponível em: https://www.diariodopresal.wordpress.com/o-que-e-o-pre-sal/. Acesso em 25 de agosto de 2025\nSobre a camada pré-sal, é correto afirmar que:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q37-figura-1.png", "options": ["É uma formação geológica que se constituiu com a separação dos continentes sul-americanos e africano ao longo das bacias de Santos, Campos e Espírito Santo.", "É considerada um recurso renovável que se constituiu com a separação dos continentes sul-americanos e europeu ao longo das bacias de Santos, Campos e Amazônica.", "Vem sendo amplamente explorada a partir de recursos internos.", "É encontrada nos subsolos oceânicos, em áreas de escudos cristalinos.", "Mesmo não tendo valor no mercado internacional, garante autossuficiência energética ao Brasil."], "answer": "A", "explanation": null, "page": 15}, {"number": 38, "subject": "Geografia", "text": "Observe o mapa e o texto abaixo:\nFonte: Operador Nacional do Sistema Elétrico - Plano anual da operação energética dos sistemas isoladospara 2021. Disponível em:\nhttps://www.ons.org.br/AcervoDigitalDocumentosEPublicacoes/DPL-REL-0250-2020%20-%20PEN%20SISOL%202021.pdf. Acesso\nem 21 de agosto de 2025.\nOs sistemas isolados, como seu próprio nome já diz, são plataformas de geração e transmissão de\nenergia elétrica que não estão conectados ao Sistema Interligado Nacional. Atualmente, o SIN é\ncomposto de quatro subsistemas: Sul, Sudeste/Centro-Oeste, Nordeste e a maior parte da Região\nNorte. No total, são pouco mais de 200 localidades isoladas no Brasil, a maioria no Norte do país.\n[…] Os Sistemas Isolados são operados de forma independente do SIN, com suas próprias regras\ne regulamentos. Eles geralmente são administrados por empresas de distribuição de energia\nelétrica, que também são responsáveis pela construção e manutenção das linhas de transmissão e\nsubestações.\nFonte: disponível em: https://solfus.com.br/o-que-sao-sistemas-isolados/. Acesso em 21 de agosto de 2025.\nO mapa e o texto tratam de uma importante questão energética brasileira. Sobre essa questão,\njulgue as afirmações a seguir:\nI – O SIN não atende parte da região Norte do país, pois o consumo de energia nesta região é muito\nbaixo. Não há nenhum ponto de grande consumo de energia na região, além do fato de não existir\ntecnologia apropriada para transmissão de energia no ambiente amazônico;\nII – As usinas de geração de energia que atuam de forma isolada, especialmente na região Norte,\nsão basicamente movidas a óleo diesel, o que torna seu funcionamento caro e logisticamente\ncomplexo;\nIII – A questão ambiental e as distâncias entre os pontos de consumo no interior da Amazônia são\nfatores que ainda inviabilizam a interligação dessas localidades com o Sistema Interligado Nacional;\nIV – Em caso de falha em uma dessas usinas ou a falta de combustível para a geração de\neletricidade, essas localidades não possuem outras formas de receber eletricidade e permanecerão\nassim até a solução do problema na usina em questão.\nEstão corretas somente as afirmações:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q38-figura-1.png", "options": ["I e II.", "II e III.", "III e IV.", "I, II e III.", "II, III e IV."], "answer": "E", "explanation": null, "page": 16}, {"number": 39, "subject": "Geografia", "text": "Uma das características da globalização é a intensificação dos fluxos de mercadorias pelo\nespaço mundial. A expansão do comércio internacional decorre da expansão dos mercados\ne da modernização dos sistemas de transportes, além da adoção de acordos multilaterais e da\nconstituição de blocos econômicos regionais, como é o caso do MERCOSUL.\nAssinale a alternativa que apresenta, respectivamente, em que tipo de bloco econômico está\ninserido o MERCOSUL e suas principais características.", "support": null, "support_image": null, "options": ["Zona de livre comércio, há a busca apenas pela liberalização gradativa do fluxo de mercadorias e de capitais dentro dos limites dos blocos.", "União aduaneira, há a eliminação de tarifas alfandegarias nas relações comerciais no interior do bloco e define-se uma Tarifa Externa Comum.", "Mercado comum, há a eliminação das barreiras alfandegárias e há a liberalização da circulação de bens, capitais, serviços e pessoas.", "União econômica e monetária, há um estágio mais avançado e adoção de uma moeda comum.", "Acordo Geral sobre Comércio de Serviços, há um intercâmbio de serviços e trocas internacionais."], "answer": "B", "explanation": null, "page": 17}, {"number": 40, "subject": "Geografia", "text": "Com base nos dados demonstrados nos mapas abaixo, aponte, respectivamente, um fator\nque permitiu a variação demonstrada e uma dificuldade enfrentada pelo Estado a partir\ndessa variação.\nFonte: IBGE, Pirâmide Etária. Disponível em:\nhttps://educa.ibge.gov.br/jovens/conheca-o-brasil/populacao/18318-piramide-etaria.html. Acesso em: 18 de agosto de 2025", "support": null, "support_image": "/militares-2026/esa-2026-geral-q40-figura-1.png", "options": ["Acesso aos programas de vacinação infantil e aumento nos gastos com o sistema de educação.", "Acesso a sistemas de saneamento básico e aumento na necessidade de geração de emprego.", "Acesso a sistemas de educação e aumento na demanda por moradias populares.", "Acesso a avanços da medicina e aumento nos gastos com o sistema de saúde.", "Acesso ao mercado de trabalho pelas mulheres e aumento na demanda por creches."], "answer": "D", "explanation": null, "page": 17}, {"number": 41, "subject": "Língua Inglesa", "text": "Read the message that an NCO Academy student on vacation wrote to his comrade who\nlives in Três Corações, Minas Gerais.\nDear Lopes,\nI arrived _____ Salvador three weeks ago. I spent two days _____ Itaparica Island and then\nwent to the Green Coast by hitching a ride. The beaches there are great for surfing,especially\nMonte Gordo. I had a great time there. After 3 days, I went to Porto Seguro _____ plane and\nstayed there for another 3 days. I was so tired that I fell asleep all the way back _____ Salvador.\nWhen I got there, I took a shuttle from the bus station to the airport. When the shuttle arrived\n_____ the airport, I got _____ the vehicle without paying. I was so embarrassed but I apologized\nto the driver for that, and everything was OK. I am travelling back to Três Corações next week.\nI hope everything is ok with you!\nTake care,\nSarmento\nFill in the blanks with the suitable prepositions.", "support": null, "support_image": null, "options": ["in – on – by – to – at – off", "at – in – of – of – in – out", "in – on – by – to – in – off", "at – on – by – in – for – off", "at – in – of – of – for – out"], "answer": "A", "explanation": null, "page": 18}, {"number": 42, "subject": "Língua Inglesa", "text": "Mark the correct option that rewrite the following sentence in the plural:\n“A soldier doesn’t hold this grenade loosely, and he always wears protective equipment.”", "support": null, "support_image": null, "options": ["Soldiers doesn’t hold those grenades loosely, and they always wears protective equipments.", "Soldiers don’t hold those grenades loosely, and they always wear protective equipment.", "Soldiers don’t hold these grenades loosely, and they always wears protective equipment.", "Soldiers don’t hold these grenades loosely, and they always wear protective equipment.", "Soldiers doesn’t hold these grenades loosely, and they always wears protective equipment."], "answer": "D", "explanation": null, "page": 18}, {"number": 43, "subject": "Língua Inglesa", "text": "Choose the best option to correctly complete the sentence below.\n- Good morning, Captain Louis. Isn’t it a nice day to go for a swim?\n- It surely is, but there isn’t a pool in the area. We have to pick up another sport,\n____________?", "support": null, "support_image": null, "options": ["haven’t we?", "don’t we?", "do you?", "is there?", "haven’t you?"], "answer": "B", "explanation": null, "page": 18}, {"number": 44, "subject": "Língua Inglesa", "text": "Read the following U.S. Army post. Then, choose the option that best reflects the main idea\nof the message.\nFONTE: US ARMY. X, 25 abr. 2025. Disponível em: https://x.com/USArmy/status/1915511067100188876. Acesso em: 02 de setembro de 2025", "support": null, "support_image": "/militares-2026/esa-2026-geral-q44-figura-1.png", "options": ["The Army’s goal was achieved sooner than expected.", "There are more than 15,600 new soldiers in the American Army in 2025.", "American soldiers use their hands to defend the country.", "More than 15,000 American soldiers are not going to buy a new uniform.", "The Army’s goal was to reenlist more than 20,000 soldiers."], "answer": "A", "explanation": null, "page": 19}, {"number": 45, "subject": "Língua Inglesa", "text": "Mark the correct option that change the adjectives in parentheses into the correct form of\nthe superlative.\nTHE PHYSICAL FITNESS COMPETITION\nThe men of Platoon Number 3 are having a competition. They are tested for fitness and\nmilitary skills such as shooting, attack and ambush drills, and night patrolling. The (important)\ntest of their fitness is the ten-mile endurance march, where they have to run and march ten miles\nin fighting order in their (good) time. There is a prize for the first one to finish. The soldier with\nthe (impressive) performance will have to compete again with Platoon Number 4.", "support": null, "support_image": null, "options": ["importantest – best – less impressive.", "most important – better – least impressive.", "most important – best – least impressive.", "more important – more good – few impressive.", "importantest – better – less impressive."], "answer": "C", "explanation": null, "page": 19}, {"number": 46, "subject": "Língua Inglesa", "text": "Read the text and choose the incorrect statement about it.\nMODERN PEACEKEEPING OPERATIONS\nModern peacekeeping operations are inherently complex and place considerable demands\non deployed personnel. At present, the most prevalent category of United Nations\npeacekeepers consists of infantry soldiers. However, there is an increasing requirement for\nspecialized personnel, referred to as “enablers,” which includes engineers, helicopter crews,\ntransport units, communications specialists, and medical staff.\nPrior to deployment, it is essential that troops undergo rigorous and comprehensive training.\nThey must be adequately prepared to respond effectively to hostile scenarios, such as\nambushes. Furthermore, conduct and discipline are critical components of the training regimen\nand are vital to operational success.\nUN uniformed personnel are drawn from over 120 nations, bringing with them a wealth of\ncultural diversity and professional experience. This diversity significantly enriches the mission\nand enhances the capacity of peacekeeping forces to operate in varied and challenging\nenvironments.\nFonte: Manutenção da Paz - Nações Unidas. Disponível em: https://peacekeeping.un.org/en/military/. Acesso em: 05 de setembro de 2025", "support": null, "support_image": null, "options": ["Modern peacekeeping operations demands mandatory pre-deployment training.", "Peacekeepers must be trained not only in tactical response but also in behavioral standards.", "Infantry soldiers remain the most common type of UN peacekeeper.", "UN peacekeeping missions require personnel from diverse professional backgrounds.", "The diversity of UN personnel poses challenges to mission cohesion and effectiveness."], "answer": "E", "explanation": null, "page": 20}, {"number": 47, "subject": "Língua Inglesa", "text": "Mark the correct option that complete the dialogue with the respective suitable\npossessives.\nTHE DAY BEFORE A FIELD TRAINING EXERCISE\nLieutenant Santos: Gomes, Is that your backpack on the bench?\nCorporal Gomes: No, sir. Sergeant Silvia Smith left it there. I think that’s _____ .\nLieutenant Santos: And what about this helmet with a red stripe?\nCorporal Gomez: That one belongs to me, Sir. It is _____. I always mark _____ gear with a\nred stripe.\nLieutenant Santos: Good habit! Where is the privates’ equipment?\nCorporal Gomez: They have already put _____ in the locker room, sir.", "support": null, "support_image": null, "options": ["his – my – mine - their", "hers – mine – my - their", "her – my – mine - their", "her – mine – mine - theirs", "hers – mine – my - theirs"], "answer": "E", "explanation": null, "page": 20}, {"number": 48, "subject": "Língua Inglesa", "text": "Read the comic strip below:\nFonte: DAVIS, Jim. Garfield. https://www.cbr.com/garfield-funniest-comic-strips/. Acesso em: 02 de setembro 2025.\nChoose the best meaning of the phrasal verb “to chow down”:", "support": null, "support_image": "/militares-2026/esa-2026-geral-q48-figura-1.png", "options": ["To do something evil.", "To eat quickly and with enthusiasm.", "To pay attention to someone.", "To lower something.", "To reduce intensity."], "answer": "B", "explanation": null, "page": 21}, {"number": 49, "subject": "Língua Inglesa", "text": "Check the alternative that only contains verbs in the simple past.\nSophie: What happened here?\nJake: I broke the chair while I was trying to fix it.\nSophie: Why were you fixing it? You can’t do that kind of work.\nJake: I thought it was easy.\nSophie: Next time, ask for help. You can’t just try everything on your own.\nJake: I know… I’ll be more careful.", "support": null, "support_image": null, "options": ["happened – broke – fix", "broke – fixing – thought", "were – can’t – work", "broke – was – thought", "happened – broke – try"], "answer": "D", "explanation": null, "page": 21}, {"number": 50, "subject": "Língua Inglesa", "text": "Read the text and mark the wrong statement about it.\nLUCKY LANDING IN BRAZIL\nIt was a lucky escape for the crew and passengers on this jet, as it managed to make an\nemergency landing in Brasilia on Friday after its front wheels failed to deploy.\nNone of the 49 passengers or crew of 5 on the Avianca Brazil Fokker 100 jet were injured in the\nlanding, as the pilot managed to land the plane on its rear landing gear before lowering the nose\nonto the runway.\nThe pilot had declared the emergency after spotting the fault and then circled the Brazilian\ncapital to shed fuel and reduce the weight of the jet before attempting the landing.\nAfter the plane successfully touched down, airport fire crews sprayed it with foam to prevent it\nfrom setting alight.\nFonte: News in Levels. Disponível em:\nhttps://www.newsinlevels.com/products/lucky-landing-in-brazil-level-3/. Acesso em: 05 de setembro de 2025", "support": null, "support_image": null, "options": ["The airplane touched down using its back wheels, then lowered its front part.", "The pilot flew around the city to burn fuel and make the plane lighter before landing.", "Firefighters covered the jet with foam after it landed to stop a fire from starting.", "The crew were hurt when the plane landed without its front wheels.", "The pilot noticed that something was wrong and told the airport before trying to land."], "answer": "D", "explanation": null, "page": 22}]}'::jsonb AS body)
INSERT INTO public.questions (exam_id,number,subject,text,support,support_image,options,answer,explanation)
SELECT e.id,(q->>'number')::integer,q->>'subject',q->>'text',q->>'support',q->>'support_image',q->'options',q->>'answer',q->>'explanation'
FROM data CROSS JOIN LATERAL jsonb_array_elements(body->'questions') q JOIN public.exams e ON e.slug=body->>'slug'
ON CONFLICT (exam_id,number) DO UPDATE SET subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation;
COMMIT;
